examples.template:
LazyVerticalGrid(
    columns = GridCells.Adaptive(minSize = ({{minItemWidth}} * 16).dp),
    modifier = Modifier.height(MonarchTheme.spacing.space24 * 6 + MonarchTheme.spacing.space8),
    horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space4),
    verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space4),
) {
    items(items = projects, key = { it }) { project ->
        MonarchCard {
            MonarchText(text = project, style = MonarchTextStyle.Subheading)
            MonarchText(text = {{description}}, style = MonarchTextStyle.Caption)
            MonarchText(text = {{body}}, style = MonarchTextStyle.Body)
        }
    }
}

examples.code:
LazyVerticalGrid(
    columns = GridCells.Adaptive(minSize = (12 * 16).dp),
    modifier = Modifier.height(MonarchTheme.spacing.space24 * 6 + MonarchTheme.spacing.space8),
    horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space4),
    verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space4),
) {
    items(items = projects, key = { it }) { project ->
        MonarchCard {
            MonarchText(text = project, style = MonarchTextStyle.Subheading)
            MonarchText(text = "Updated this week", style = MonarchTextStyle.Caption)
            MonarchText(text = "3 open tasks", style = MonarchTextStyle.Body)
        }
    }
}

FlowRow(
    maxItemsInEachRow = 2,
    horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space4),
    verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space4),
) {
    listOf("Open", "Pending", "Solved", "Closed").forEach { status ->
        MonarchCard(modifier = Modifier.weight(1f)) { MonarchText(text = status) }
    }
}
